import fs from 'node:fs';
import path from 'node:path';
import assert from 'node:assert/strict';
const [runtime,storage,mode,output]=process.argv.slice(2);
assert(runtime&&storage&&['seed','run'].includes(mode)&&output);
process.env.GITNEXUS_LBUG_BUFFER_POOL_SIZE=String(256*1024*1024);
process.env.GITNEXUS_SHARED_STORE='off';
const {createKnowledgeGraph}=await import(path.join(runtime,'gitnexus/dist/core/graph/graph.js'));
const {reconcileGraphNodeIdentities}=await import(path.join(runtime,'gitnexus/dist/core/incremental/write-reconciliation.js'));
const adapter=await import(path.join(runtime,'gitnexus/dist/core/lbug/lbug-adapter.js'));
const graph=createKnowledgeGraph(),count=65536;
for(let i=0;i<count;i++)graph.addNode({id:`Function:src/owner${Math.floor(i/32)}.ts:fn${i}`,label:'Function',properties:{name:`fn${i}`,filePath:`src/owner${Math.floor(i/32)}.ts`,startLine:(i%32)*4,endLine:(i%32)*4+2}});
fs.mkdirSync(storage,{recursive:true});
const result={runtime,mode,count,node:process.version,bufferPoolBytes:256*1024*1024,iterations:[]};
try{
  await adapter.initLbug(path.join(storage,'lbug'),{skipFts:true});
  if(mode==='seed'){
    await adapter.loadGraphToLbug(graph,storage,storage,undefined,undefined,undefined,'none');
    await adapter.tryFlushWAL();
  }else{
    for(let i=0;i<4;i++){
      global.gc();
      const before=process.memoryUsage(),start=performance.now();
      assert.equal((await reconcileGraphNodeIdentities(graph,adapter.executeQuery,'memory-probe')).nodes,count);
      const ms=performance.now()-start,after=process.memoryUsage();
      global.gc();
      result.iterations.push({i,ms,before,after,afterGc:process.memoryUsage(),maxRssKiB:process.resourceUsage().maxRSS});
      fs.writeFileSync(output,JSON.stringify(result,null,2)+'\n');
    }
  }
}finally{await adapter.closeLbug();}
result.maxRssKiB=process.resourceUsage().maxRSS;
fs.writeFileSync(output,JSON.stringify(result,null,2)+'\n');
console.log(JSON.stringify({mode,maxRssKiB:result.maxRssKiB,iterations:result.iterations.map(x=>({i:x.i,ms:x.ms,heapAfterGc:x.afterGc.heapUsed,rssAfterGc:x.afterGc.rss}))}));

