import path from 'node:path';
import assert from 'node:assert/strict';
const [runtime,storage,output]=process.argv.slice(2);
process.env.GITNEXUS_LBUG_BUFFER_POOL_SIZE=String(256*1024*1024);
process.env.GITNEXUS_SHARED_STORE='off';
const {createKnowledgeGraph}=await import(path.join(runtime,'gitnexus/dist/core/graph/graph.js'));
const {reconcileGraphNodeIdentities}=await import(path.join(runtime,'gitnexus/dist/core/incremental/write-reconciliation.js'));
const adapter=await import(path.join(runtime,'gitnexus/dist/core/lbug/lbug-adapter.js'));
const graph=createKnowledgeGraph(),count=65536,size=4096;
for(let i=0;i<count;i++)graph.addNode({id:`Function:src/owner${Math.floor(i/32)}.ts:fn${i}`,label:'Function',properties:{name:`fn${i}`,filePath:`src/owner${Math.floor(i/32)}.ts`,startLine:(i%32)*4,endLine:(i%32)*4+2}});
const result={runtime,count,size,node:process.version,bufferPoolBytes:256*1024*1024,iterations:[]};
let calls=0;
async function paged(cypher){
  const identities=[];
  for(let offset=0;;offset+=size){
    const q=cypher.replace(' RETURN collect(',` WITH n ORDER BY n.id SKIP ${offset} LIMIT ${size} RETURN collect(`);
    const rows=await adapter.executeQuery(q); calls++;
    assert.equal(rows.length,1); assert(Array.isArray(rows[0].identities)); assert(rows[0].identities.length<=size);
    identities.push(...rows[0].identities);
    if(rows[0].identities.length<size)break;
  }
  return [{identities}];
}
try{
  await adapter.initLbug(path.join(storage,'lbug'),{skipFts:true});
  for(let i=0;i<4;i++){
    global.gc();calls=0;
    const before=process.memoryUsage(),start=performance.now();
    assert.equal((await reconcileGraphNodeIdentities(graph,paged,'paged-memory-probe')).nodes,count);
    const ms=performance.now()-start,after=process.memoryUsage();global.gc();
    result.iterations.push({i,ms,calls,before,after,afterGc:process.memoryUsage(),maxRssKiB:process.resourceUsage().maxRSS});
    fs.writeFileSync(output,JSON.stringify(result,null,2)+'\n');
  }
}finally{await adapter.closeLbug();}
result.maxRssKiB=process.resourceUsage().maxRSS;
fs.writeFileSync(output,JSON.stringify(result,null,2)+'\n');
console.log(JSON.stringify(result.iterations.map(x=>({i:x.i,ms:x.ms,calls:x.calls,rssAfterGc:x.afterGc.rss,maxRssKiB:x.maxRssKiB}))));

